def load(p):
    with open(p,'r',encoding='utf-8') as f: return yaml.safe_load(f) or {}
def main():
    root=Path(sys.argv[1]) if len(sys.argv)>1 else Path('.')
    version=(root/'VERSION').read_text(encoding='utf-8').strip(); failures=[]; checks=[]; final=load(root/'CONTROL_STACK.yml').get('final_step', 186)
    nums=[]
    for p in (root/'docs').glob('*.md'):
        m=re.match(r'^(\d+)-',p.name)
        if m: nums.append(int(m.group(1)))
    nums=sorted(nums)
    if nums != list(range(nums[-1]+1)) or nums[-1] != final: failures.append(f'numbered docs not contiguous through {final}')
    checks.append({'invariant_id':'INV-001','passed':not any('numbered docs' in f for f in failures)})
    required_roots=['INVARIANT_CATALOG.yml', 'TRACEABILITY_MATRIX.yml', 'CHANGE_IMPACT_MATRIX.yml', 'MIGRATION_LEDGER.yml', 'FIXTURE_CORPUS.yml', 'CONTROL_STACK.yml', 'CUBE_INDEX.yml', 'STATUS_VOCABULARY.yml', 'REFERENCE_MAP.yml', 'QUERY_REGRESSION_SUITE.yml', 'CLAIM_LANGUAGE_LEDGER.yml', 'PROVENANCE_LEDGER.yml', 'CLAIM_GRAPH.yml', 'EVIDENCE_PACKET_INDEX.yml', 'CONTRADICTION_LEDGER.yml', 'FRESHNESS_POLICY.yml', 'DEFEASANCE_PROPAGATION.yml', 'RELEASE_GATE_POLICY.yml', 'ACCEPTANCE_CRITERIA_MATRIX.yml', 'RELEASE_DECISION_LEDGER.yml', 'WAIVER_EXCEPTION_LEDGER.yml', 'RISK_ACCEPTANCE_LEDGER.yml', 'ASSURANCE_CASE_SKELETON.yml', 'BUILD_REPRODUCIBILITY_LEDGER.yml', 'ATTESTATION_BOUNDARY_LEDGER.yml', 'EVIDENCE_CHAIN_CUSTODY.yml', 'EXECUTION_LOG_LEDGER.yml', 'ROLLBACK_RETRACTION_PLAN.yml', 'PUBLIC_RELEASE_ATTESTATION.yml', 'OBSERVABILITY_MONITORING_PLAN.yml', 'AUDIT_SAMPLING_PLAN.yml', 'FEEDBACK_INTAKE_LEDGER.yml', 'DOWNSTREAM_RELIANCE_LEDGER.yml', 'DRIFT_ANOMALY_LEDGER.yml', 'EXERCISE_INCIDENT_DRILL_LEDGER.yml', 'REMEDIATION_TRIAGE_POLICY.yml', 'SEVERITY_CLASSIFICATION_MATRIX.yml', 'SERVICE_OBJECTIVE_LEDGER.yml', 'CORRECTIVE_ACTION_REGISTER.yml', 'COMMUNICATION_ESCALATION_LEDGER.yml', 'CLOSURE_VERIFICATION_LEDGER.yml', 'ROLE_AUTHORITY_MATRIX.yml', 'ACCOUNTABILITY_ASSIGNMENT_LEDGER.yml', 'SEGREGATION_OF_DUTIES_POLICY.yml', 'DELEGATION_HANDOFF_LEDGER.yml', 'APPROVAL_CONSENT_LEDGER.yml', 'ACCOUNTABILITY_REVIEW_LEDGER.yml', 'CONTESTATION_INTAKE_LEDGER.yml', 'APPEAL_REVIEW_POLICY.yml', 'DISSENT_MINORITY_REPORT_LEDGER.yml', 'HARM_IMPACT_REVIEW_LEDGER.yml', 'REDRESS_REVERSAL_LEDGER.yml', 'STAKEHOLDER_CHALLENGE_REGISTER.yml','PRIVACY_MINIMIZATION_POLICY.yml','CONFIDENTIALITY_ACCESS_MATRIX.yml','DISCLOSURE_PUBLICATION_REVIEW.yml','RETENTION_DELETION_LEDGER.yml','SENSITIVE_DATA_CLASSIFICATION.yml','PRIVACY_RISK_REVIEW_LEDGER.yml','SECURITY_THREAT_MODEL.yml','ABUSE_MISUSE_CASE_REGISTER.yml','VULNERABILITY_DISCLOSURE_INTAKE.yml','SECURITY_HARDENING_BASELINE.yml','TRUST_BOUNDARY_LEDGER.yml','SECRET_KEY_MATERIAL_POLICY.yml','MAINTAINERSHIP_STEWARDSHIP_LEDGER.yml','DEPENDENCY_UPDATE_POLICY.yml','PRESERVATION_ARCHIVAL_PLAN.yml','PORTABILITY_INTEROPERABILITY_MATRIX.yml','SUCCESSION_CONTINUITY_PLAN.yml','SUNSET_END_OF_LIFE_LEDGER.yml','LICENSE_REUSE_POLICY.yml','ATTRIBUTION_CITATION_LEDGER.yml','THIRD_PARTY_CONTENT_REGISTER.yml','CONTRIBUTOR_PROVENANCE_LEDGER.yml','DERIVATIVE_REDISTRIBUTION_POLICY.yml','COMPLIANCE_BOUNDARY_LEDGER.yml','ETHICAL_IMPACT_ASSESSMENT.yml','PUBLIC_INTEREST_BALANCING_LEDGER.yml','AFFECTED_PARTY_ANALYSIS.yml','FAIRNESS_BIAS_REVIEW_LEDGER.yml','MISUSE_SENSITIVE_RELEASE_POLICY.yml','BENEFIT_HARM_REGISTER.yml','ACCESSIBILITY_REVIEW_PLAN.yml','READABILITY_PLAIN_LANGUAGE_LEDGER.yml','DISCOVERABILITY_NAVIGATION_MAP.yml','LOCALIZATION_TRANSLATION_BOUNDARY.yml','USER_GUIDANCE_ONBOARDING_LEDGER.yml','INCLUSIVE_ACCESS_RISK_REGISTER.yml']
    for rel in required_roots:
        if not (root/rel).exists(): failures.append(f'missing artifact {rel}')
    checks.append({'invariant_id':'INV-002','passed':not any('missing artifact' in f for f in failures)})
    misses=[]
    for fam,schema in BASE_MAP.items():
        rec=root/'REGISTERS'/f'{version}-{fam}.yml'; sch=root/'REGISTERS/schemas'/schema
        if not rec.exists(): misses.append((str(rec.relative_to(root)),'record_missing')); continue
        if not sch.exists(): misses.append((str(sch.relative_to(root)),'schema_missing')); continue
        d=load(rec); req=load(sch).get('required_fields',[])
        for f in req:
            if f not in d: misses.append((str(rec.relative_to(root)),f))
    if misses: failures.append('required-field misses: '+repr(misses[:10]))
    checks.append({'invariant_id':'INV-005','passed':not misses})
    defined=set()
    for cf in load(root/'STATUS_VOCABULARY.yml').get('code_families',[]): defined.update((cf.get('codes') or {}).keys())
    tok_re=re.compile(r'([A-Z]{1,5}\d+)(?:_[A-Za-z0-9_]+)?')
    undef=[]
    for p in sorted((root/'REGISTERS').glob(f'{version}-*.yml')):
        for m in tok_re.finditer(p.read_text(encoding='utf-8',errors='ignore')):
            if m.group(1) not in defined: undef.append((str(p.relative_to(root)),m.group(1)))
    if undef: failures.append('undefined status tokens: '+repr(undef[:10]))
    checks.append({'invariant_id':'INV-006','passed':not undef})
    cs=load(root/'CONTROL_STACK.yml'); by={s.get('step'):s for s in cs.get('steps',[])}
    bad=[]
    for n in range(144,final):
        if by.get(n,{}).get('successor_step') != n+1: bad.append(n)
    if cs.get('final_step') != final or by.get(final,{}).get('successor_step') is not None: bad.append('final')
    if bad: failures.append('control stack chain bad: '+repr(bad[:10]))
    checks.append({'invariant_id':'INV-007','passed':not bad})
    missing=[]
    for o in load(root/'CUBE_INDEX.yml').get('current_release_observations',[]):
        for s in o.get('source_artifacts',[]):
            if not (root/s).exists(): missing.append(s)
    if missing: failures.append('cube source missing: '+repr(missing[:10]))
    checks.append({'invariant_id':'INV-008','passed':not missing})
    report_requirements=[('INV-009',f'REGISTERS/reference-integrity-report-{version}.yml'),('INV-010',f'REGISTERS/query-regression-report-{version}.yml'),('INV-013',f'REGISTERS/traceability-report-{version}.yml'),('INV-016',f'REGISTERS/claim-graph-report-{version}.yml'),('INV-017',f'REGISTERS/release-gate-report-{version}.yml'),('INV-018',f'REGISTERS/build-reproducibility-report-{version}.yml'),('INV-019',f'REGISTERS/observability-report-{version}.yml'),('INV-020',f'REGISTERS/remediation-triage-report-{version}.yml'),('INV-021',f'REGISTERS/role-authority-report-{version}.yml'),('INV-022',f'REGISTERS/contestation-intake-report-{version}.yml'),('INV-023',f'REGISTERS/privacy-risk-review-report-{version}.yml'),('INV-024',f'REGISTERS/security-threat-model-report-{version}.yml'),('INV-025',f'REGISTERS/maintainership-stewardship-report-{version}.yml'),('INV-026',f'REGISTERS/license-reuse-report-{version}.yml'),('INV-027',f'REGISTERS/compliance-boundary-report-{version}.yml'),('INV-028',f'REGISTERS/ethical-impact-report-{version}.yml'),('INV-029',f'REGISTERS/benefit-harm-report-{version}.yml'),('INV-030',f'REGISTERS/accessibility-review-report-{version}.yml'),('INV-031',f'REGISTERS/readability-plain-language-report-{version}.yml'),('INV-032',f'REGISTERS/discoverability-navigation-report-{version}.yml'),('INV-033',f'REGISTERS/localization-translation-report-{version}.yml'),('INV-034',f'REGISTERS/user-guidance-onboarding-report-{version}.yml'),('INV-035',f'REGISTERS/inclusive-access-risk-report-{version}.yml')]
    for inv,rel in report_requirements:
        ok=(root/rel).exists() and bool(load(root/rel)); checks.append({'invariant_id':inv,'passed':ok})
        if not ok: failures.append(f'required report missing or unreadable: {rel}')
    for rel in ['CLAIM_LANGUAGE_LEDGER.yml','PROVENANCE_LEDGER.yml','MIGRATION_LEDGER.yml','FIXTURE_CORPUS.yml','RELEASE_GATE_POLICY.yml','ASSURANCE_CASE_SKELETON.yml','PUBLIC_RELEASE_ATTESTATION.yml','OBSERVABILITY_MONITORING_PLAN.yml','REMEDIATION_TRIAGE_POLICY.yml','CLOSURE_VERIFICATION_LEDGER.yml', 'ROLE_AUTHORITY_MATRIX.yml', 'ACCOUNTABILITY_ASSIGNMENT_LEDGER.yml', 'SEGREGATION_OF_DUTIES_POLICY.yml', 'DELEGATION_HANDOFF_LEDGER.yml', 'APPROVAL_CONSENT_LEDGER.yml', 'ACCOUNTABILITY_REVIEW_LEDGER.yml', 'CONTESTATION_INTAKE_LEDGER.yml', 'APPEAL_REVIEW_POLICY.yml', 'DISSENT_MINORITY_REPORT_LEDGER.yml', 'HARM_IMPACT_REVIEW_LEDGER.yml', 'REDRESS_REVERSAL_LEDGER.yml', 'STAKEHOLDER_CHALLENGE_REGISTER.yml','PRIVACY_MINIMIZATION_POLICY.yml','CONFIDENTIALITY_ACCESS_MATRIX.yml','DISCLOSURE_PUBLICATION_REVIEW.yml','RETENTION_DELETION_LEDGER.yml','SENSITIVE_DATA_CLASSIFICATION.yml','PRIVACY_RISK_REVIEW_LEDGER.yml','SECURITY_THREAT_MODEL.yml','ABUSE_MISUSE_CASE_REGISTER.yml','VULNERABILITY_DISCLOSURE_INTAKE.yml','SECURITY_HARDENING_BASELINE.yml','TRUST_BOUNDARY_LEDGER.yml','SECRET_KEY_MATERIAL_POLICY.yml','MAINTAINERSHIP_STEWARDSHIP_LEDGER.yml','DEPENDENCY_UPDATE_POLICY.yml','PRESERVATION_ARCHIVAL_PLAN.yml','PORTABILITY_INTEROPERABILITY_MATRIX.yml','SUCCESSION_CONTINUITY_PLAN.yml','SUNSET_END_OF_LIFE_LEDGER.yml','LICENSE_REUSE_POLICY.yml','ATTRIBUTION_CITATION_LEDGER.yml','THIRD_PARTY_CONTENT_REGISTER.yml','CONTRIBUTOR_PROVENANCE_LEDGER.yml','DERIVATIVE_REDISTRIBUTION_POLICY.yml','COMPLIANCE_BOUNDARY_LEDGER.yml','ETHICAL_IMPACT_ASSESSMENT.yml','PUBLIC_INTEREST_BALANCING_LEDGER.yml','AFFECTED_PARTY_ANALYSIS.yml','FAIRNESS_BIAS_REVIEW_LEDGER.yml','MISUSE_SENSITIVE_RELEASE_POLICY.yml','BENEFIT_HARM_REGISTER.yml','ACCESSIBILITY_REVIEW_PLAN.yml','READABILITY_PLAIN_LANGUAGE_LEDGER.yml','DISCOVERABILITY_NAVIGATION_MAP.yml','LOCALIZATION_TRANSLATION_BOUNDARY.yml','USER_GUIDANCE_ONBOARDING_LEDGER.yml','INCLUSIVE_ACCESS_RISK_REGISTER.yml']:
        if not load(root/rel): failures.append(f'artifact shape insufficient: {rel}')
    mig=load(root/'MIGRATION_LEDGER.yml')
    if not str(mig.get('source_version','')).startswith('rev') or mig.get('target_version')!=version or 'transition_class' not in mig: failures.append('migration ledger shape insufficient')
    pol=[f.get('polarity') for f in load(root/'FIXTURE_CORPUS.yml').get('fixtures',[])]
    if 'positive' not in pol or 'negative' not in pol: failures.append('fixture corpus lacks positive or negative fixture')
    report={'invariant_report_version':f'{version}-invariant-report-v6','archive_version':version,'status':'INV4_invariant_report_passed' if not failures else 'INV7_unsafe_invariant_claim','summary':{'checks':len(checks),'failures':len(failures)},'checks':checks,'failures':failures}
    print(yaml.safe_dump(report,sort_keys=False,allow_unicode=True).rstrip()); return 1 if failures else 0
if __name__=='__main__': raise SystemExit(main())
